    #[arg(long, default_value = "utf8-lossy", help = "Specify input encoding")]
    encoding: String,

    #[command(subcommand)]
    command: Option<Commands>,
}

#[derive(Subcommand)]
enum Commands {
    Completion {
        #[arg(value_name = "SHELL")]
        shell: String,
    },
}

fn main() -> io::Result<()> {
    let cli = Cli::parse();

    if let Some(Commands::Completion { shell }) = cli.command {
        // Handle completion command
        return Ok(());
    }

    let input: Box<dyn BufRead> = match cli.file {
        Some(path) => Box::new(BufReader::new(File::open(path)?)),
        None => Box::new(BufReader::new(io::stdin())),
    };

    let mut lines = Vec::new();
    for line in input.lines() {
        let line = match cli.encoding.as_str() {
            "utf8" => line?,
            _ => String::from_utf8_lossy(&line?.into_bytes()).into_owned(),
        };
        lines.push(line);
    }

    if lines.is_empty() {
        return Ok(());
    }

    let vscale = cli.vertical_scale;
    let hscale = cli.horizontal_scale;

    let num_rows = ((lines.len() as f64 * vscale).ceil() as usize).div_ceil(4);
    let mut minimap = Vec::new();

    for r in 0..num_rows {
        // Collect lines for this Braille row (4 dot rows)
        let mut dot_rows = vec![Vec::<(usize, usize)>::new(); 4];
        for dr in 0..4 {
            let row_idx = r * 4 + dr;
            // Which input lines map to this dot row?
            // All lines i where floor(i * vscale) == row_idx
            // This is equivalent to i in [row_idx / vscale, (row_idx + 1) / vscale)
            let i_start = (row_idx as f64 / vscale).ceil() as usize;
            let i_end = ((row_idx + 1) as f64 / vscale).ceil() as usize;

            let mut min_dot: Option<usize> = None;
            let mut max_dot: Option<usize> = None;

            for i in i_start..i_end {
                if i < lines.len() {
                    let line = &lines[i];
                    if let Some(first) = line.find(|c: char| !c.is_whitespace()) {
                        let last = line.rfind(|c: char| !c.is_whitespace()).unwrap();

                        let first_char_idx = line[..first].chars().count();
                        let last_char_idx = line[..last].chars().count();

                        let d_start = (first_char_idx as f64 * hscale).floor() as usize;
                        let d_end = (last_char_idx as f64 * hscale).floor() as usize;

                        min_dot = Some(min_dot.map_or(d_start, |m| m.min(d_start)));
                        max_dot = Some(max_dot.map_or(d_end, |m| m.max(d_end)));
                    }
                }
            }
            if let (Some(start), Some(end)) = (min_dot, max_dot) {
                dot_rows[dr].push((start, end));
            }
        }

        // Now render the row
        let mut max_col = 0;
        for dr in 0..4 {
            for &(_, end) in &dot_rows[dr] {
                max_col = max_col.max(end);
            }
        }

        let num_chars = (max_col + 1).div_ceil(2);
        let mut row_chars = vec![0u8; num_chars];

        for dr in 0..4 {
            for &(start, end) in &dot_rows[dr] {
                for col in start..=end {
                    let char_idx = col / 2;
                    let bit = if col % 2 == 0 {
                        match dr { 0 => 0, 1 => 1, 2 => 2, 3 => 6, _ => unreachable!() }
                    } else {
                        match dr { 0 => 3, 1 => 4, 2 => 5, 3 => 7, _ => unreachable!() }
                    };
                    if char_idx < num_chars {
                        row_chars[char_idx] |= 1 << bit;
                    }
                }
            }
        }

        let mut output_line = String::new();
        for &bits in &row_chars {
            let c = std::char::from_u32(0x2800 + bits as u32).unwrap();
            output_line.push(c);
        }

        if let Some(p) = cli.padding {
            while output_line.chars().count() < p {
                output_line.push(' ');
            }
        }
        println!("{}", output_line);
    }

    Ok(())
}
