        command: None,
        shell: None,
    };

    while let Some(arg) = args.next() {
        match arg.as_str() {
            "-H" | "--horizontal-scale" => {
                if let Some(val) = args.next() {
                    cli.horizontal_scale = val.parse().unwrap_or(1.0);
                }
            }
            "-V" | "--vertical-scale" => {
                if let Some(val) = args.next() {
                    cli.vertical_scale = val.parse().unwrap_or(1.0);
                }
            }
            "--padding" => {
                if let Some(val) = args.next() {
                    cli.padding = Some(val.parse().unwrap_or(0));
                }
            }
            "--encoding" => {
                if let Some(val) = args.next() {
                    cli.encoding = val;
                }
            }
            "--version" => cli.version = true,
            "-h" | "--help" => cli.help = true,
            "completion" => {
                cli.command = Some("completion".to_string());
                cli.shell = args.next();
            }
            "help" => {
                cli.help = true;
            }
            _ if arg.starts_with('-') => {}
            _ => {
                if cli.file.is_none() {
                    cli.file = Some(PathBuf::from(arg));
                }
            }
        }
    }
    cli
}

fn main() {
    let cli = parse_args();

    if cli.help {
        println!("A high performance code minimap generator\n\nUsage: executable [OPTIONS] [FILE] [COMMAND]\n\nCommands:\n  completion  Generate shell completion file\n  help        Print this message or the help of the given subcommand(s)\n\nArguments:\n  [FILE]  File to read\n\nOptions:\n  -H, --horizontal-scale <HSCALE>  Specify horizontal scale factor [default: 1.0]\n  -V, --vertical-scale <VSCALE>    Specify vertical scale factor [default: 1.0]\n      --padding <PADDING>          Specify padding width\n      --encoding <ENCODING>        Specify input encoding [default: utf8-lossy] [possible values: utf8-lossy, utf8]\n      --version                    Print version\n  -h, --help                       Print help");
        return;
    }
    if cli.version {
        println!("code-minimap 0.6.8");
        return;
    }

    if let Some(cmd) = cli.command {
        if cmd == "completion" {
            // Minimal placeholder for completion
            return;
        }
    }

    if let Err(e) = run(cli) {
        eprintln!("code-minimap: {}", e);
        std::process::exit(1);
    }
}

fn run(cli: Cli) -> io::Result<()> {
    let input: Box<dyn BufRead> = match cli.file {
        Some(path) => Box::new(BufReader::new(File::open(path)?)),
        None => Box::new(BufReader::new(io::stdin())),
    };

    let mut lines = Vec::new();
    for line in input.lines() {
        let line = match cli.encoding.as_str() {
            "utf8" => line.map_err(|e| io::Error::new(e.kind(), "stream did not contain valid UTF-8"))?,
            _ => {
                let bytes = line?;
                String::from_utf8_lossy(bytes.as_bytes()).into_owned()
            }
        };
        lines.push(line);
    }

    if lines.is_empty() {
        return Ok(());
    }

    let hscale = cli.horizontal_scale;
    let vscale = cli.vertical_scale;

    let num_rows = (lines.len() as f64 * vscale).ceil() as usize;
    let num_braille_rows = (num_rows + 3) / 4;

    for r in 0..num_braille_rows {
        let mut dot_rows = vec![None::<(usize, usize)>; 4];
        for dr in 0..4 {
            let row_idx = r * 4 + dr;
            let i_start = (row_idx as f64 / vscale).ceil() as usize;
            let i_end = ((row_idx + 1) as f64 / vscale).ceil() as usize;

            let mut min_dot: Option<usize> = None;
            let mut max_dot: Option<usize> = None;

            for i in i_start..i_end {
                if i < lines.len() {
                    let line = &lines[i];
                    let trimmed_end = line.trim_end();
                    if !trimmed_end.is_empty() {
                        if let Some(first_idx) = line.find(|c: char| !c.is_whitespace()) {
                            let last_idx = line.rfind(|c: char| !c.is_whitespace()).unwrap();
                            let first_char_idx = line[..first_idx].chars().count();
                            let last_char_idx = line[..last_idx].chars().count();

                            let d_start = (first_char_idx as f64 * hscale).floor() as usize;
                            let d_end = if ((last_char_idx + 1) as f64 * hscale).floor() as usize > 0 {
                                ((last_char_idx + 1) as f64 * hscale).floor() as usize - 1
                            } else {
                                0
                            };
                            min_dot = Some(min_dot.map_or(d_start, |m| m.min(d_start)));
                            max_dot = Some(max_dot.map_or(d_end, |m| m.max(d_end)));
                        }
                    }
                }
            }
            if let (Some(start), Some(end)) = (min_dot, max_dot) {
                dot_rows[dr] = Some((start, end));
            }
        }

        let mut max_col = None;
        for dr in 0..4 {
            if let Some((_, end)) = dot_rows[dr] {
                max_col = Some(max_col.map_or(end, |m| std::cmp::max(m, end)));
            }
        }

        let mut output_line = String::new();
        if let Some(mc) = max_col {
            let num_chars = (mc / 2) + 1;
            let mut row_bits = vec![0u8; num_chars];
            for dr in 0..4 {
                if let Some((start, end)) = dot_rows[dr] {
                    for col in start..=end {
                        let char_idx = col / 2;
                        let bit = if col % 2 == 0 {
                            match dr { 0 => 0, 1 => 1, 2 => 2, 3 => 6, _ => 0 }
                        } else {
                            match dr { 0 => 3, 1 => 4, 2 => 5, 3 => 7, _ => 0 }
                        };
                        if char_idx < num_chars {
                            row_bits[char_idx] |= 1 << bit;
                        }
                    }
                }
            }
            for &bits in &row_bits {
                let c = std::char::from_u32(0x2800 + bits as u32).unwrap();
                output_line.push(c);
            }
        }

        if let Some(p) = cli.padding {
            while output_line.chars().count() < p {
                output_line.push(' ');
            }
        }
        if !output_line.is_empty() || cli.padding.is_some() {
            println!("{}", output_line);
        } else if r * 4 < num_rows {
            println!();
        }
    }

    Ok(())
}
